'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({lang:0,name:'',avatar:'🧑‍🚀',xp:0,done:[],practiceDone:[],tests:[],mistakes:[],answered:0,correct:0,hearts:5,heartTime:Date.now(),dates:[],daily:{},simSeen:[],games:{},study:0,motion:true});
let state=fresh(),storageOK=true;try{const old=JSON.parse(localStorage.getItem('orbita-v1'));if(old&&Array.isArray(old.done)&&Array.isArray(old.tests))state={...state,...old}}catch{storageOK=false}
state.lang=state.lang===1?1:0;
let page='',session=null,selection=null,feedback=null,simState=null,game=null,anim=null;
const t=(pt,en)=>state.lang?en:pt, tr=x=>Array.isArray(x)?x[state.lang]:x;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const save=()=>{try{localStorage.setItem('orbita-v1',JSON.stringify(state))}catch{storageOK=false}};
function recover(){const n=Math.floor((Date.now()-state.heartTime)/1800000);if(n>0){state.hearts=Math.min(5,state.hearts+n);state.heartTime=Date.now();save()}}
recover();
function streak(){let n=0,d=new Date();if(!state.dates.includes(today()))d.setDate(d.getDate()-1);while(state.dates.includes(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`)){n++;d.setDate(d.getDate()-1)}return n}
function reward(xp){const before=Math.floor(state.xp/100);state.xp+=xp;state.daily[today()]=(state.daily[today()]||0)+xp;if(!state.dates.includes(today()))state.dates.push(today());save();notify(`+${xp} XP ✨${Math.floor(state.xp/100)>before?' · '+t('Novo nível!','Level up!'):''}`)}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
const navs=[['home','⌘',bi('Minha jornada','My journey')],['simulators','⚗',bi('Laboratório','Laboratory')],['games','✦',bi('Jogos','Games')],['exercises','✎',bi('Exercícios','Exercises')],['review','↻',bi('Revisão','Review')],['achievements','♜',bi('Conquistas','Achievements')],['profile','☺',bi('Meu perfil','My profile')],['settings','⚙',bi('Configurações','Settings')]];
function shell(content){const root=page.split('/')[0],active=['lesson','test','unit'].includes(root)?'home':root==='sim'?'simulators':root==='game'?'games':root;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="Orbita"><span class="brandmark">◎</span>orbita<span style="color:#f2a747">.</span></a><nav class="nav" aria-label="${t('Navegação principal','Main navigation')}">${navs.map(([id,icon,label])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="ico" aria-hidden="true">${icon}</span>${tr(label)}</a>`).join('')}</nav><div class="sidefoot">${t('PEQUENAS DESCOBERTAS.','SMALL DISCOVERIES.')}<strong>${t('Grandes possibilidades.','Endless possibilities.')}</strong><span>${t("Física · Ensino Médio","Physics · High School")}</span></div></aside><div><header class="topbar"><span class="crumb">${t('Seu universo de descobertas','Your universe of discoveries')}</span><div class="stats"><span style="color:#c08015" title="XP">ϟ ${state.xp} XP</span><span style="color:#c87944" title="${t('Sequência diária','Daily streak')}">♨ ${streak()}</span><span style="color:#d45976" title="${t('Vidas: uma recuperada a cada 30 minutos','Lives: one recovered every 30 minutes')}">♥ ${state.hearts}</span><button class="lang" id="language" aria-label="${t('Switch to English','Mudar para Português')}">${t('🇧🇷 PT','🇬🇧 EN')} <span class="muted">⌄</span></button><a class="avatar" href="#profile" aria-label="${t('Meu perfil','My profile')}">${state.avatar}</a></div></header><main class="page" id="main">${!storageOK?`<div class="feedback wrong">${t('O navegador não permite salvar. O progresso desta sessão pode ser perdido ao fechar.','This browser does not allow saving. Session progress may be lost when you close it.')}</div>`:''}${content}</main></div></div>`;$('#language').onclick=()=>{state.lang=1-state.lang;save();render(false)};document.documentElement.lang=t('pt-BR','en');document.title=t('Orbita · Descubra a Física','Orbita · Discover Physics')}
const done=(u,l)=>state.done.includes(`${u}-${l}`),unlocked=u=>u===0||state.tests.includes(u-1),canLesson=(u,l)=>unlocked(u)&&(l===0||done(u,l-1));
function nextLesson(){for(let u=0;u<10;u++){for(let l=0;l<4;l++)if(!done(u,l))return `lesson/${u}/${l}`;if(!state.tests.includes(u))return `test/${u}`}return 'review'}
function unitCard(u,i){let completed=u.lessons.filter((_,l)=>done(i,l)).length+(state.tests.includes(i)?1:0),open=unlocked(i);return `<article class="unit ${open&&!state.tests.includes(i)?'current':''}"><${open?'button':'div'} class="unithead" ${open?`data-unit="${i}"`:''}><span class="uniticon" style="background:${['#eee9ff','#e5f5fb','#ffeae7','#fff4d6'][i%4]}">${u.icon}</span><div><h3>${String(i+1).padStart(2,'0')} · ${tr(u.name)}</h3><p>${tr(u.topic)} · ${tr(u.intro)}</p></div><span class="end">${open?`${completed}/5`:'🔒'}</span></${open?'button':'div'}>${open?`<div class="path">${[...u.lessons.map(x=>tr(x.title)),t('Desafio final','Final challenge')].map((label,l)=>{const isdone=l===4?state.tests.includes(i):done(i,l),ready=l===4?u.lessons.every((_,j)=>done(i,j)):canLesson(i,l),url=l===4?`test/${i}`:`lesson/${i}/${l}`;return `<${ready?'a':'div'} ${ready?`href="#${url}"`:''} class="step"><span class="node ${isdone?'done':ready?'ready':''}">${isdone?'✓':l===4?'⚑':ready?'★':'•'}</span>${label}</${ready?'a':'div'}>`}).join('')}</div>`:''}</article>`}
function home(){const n=state.done.length,dayXP=state.daily[today()]||0;return `<div class="greeting"><div><h1>${t('Olá','Hello')}, ${esc(state.name||t('explorador','explorer'))}! ✨</h1><p class="muted">${t('Uma pequena descoberta. Um universo de possibilidades.','A little discovery. A universe of possibilities.')}</p></div><span class="tag">${t('NÍVEL','LEVEL')} ${1+Math.floor(state.xp/100)} · ${t('EXPLORADOR','EXPLORER')}</span></div><div class="columns"><div><section class="hero"><div><span class="eyebrow">${t('SUA PRÓXIMA DESCOBERTA','YOUR NEXT DISCOVERY')}</span><h2>${t('O mundo é um<br>laboratório.','The world is<br>your laboratory.')}</h2><p>${t('Aprenda um pouquinho. Experimente muito. A Física está em todo lugar.','Learn a little. Experiment a lot. Physics is all around you.')}</p><a class="primary" href="#${nextLesson()}">${n?t('Continuar jornada','Continue journey'):t('Vamos explorar','Let’s explore')} →</a></div><canvas id="hero-orbit" aria-label="${t('Modelo de órbita circular','Circular orbit model')}"></canvas></section><div class="sectionhead"><h2>${t('Sua trilha de descobertas','Your discovery trail')}</h2><small>${n}/40 ${t('aulas','lessons')}</small></div><div class="progress" aria-label="${t('Progresso geral','Overall progress')}"><i style="width:${(n+state.tests.length)/50*100}%"></i></div>${UNITS.map(unitCard).join('')}<p class="note">${t('Conteúdo introdutório de Física do Ensino Médio, organizado de forma independente. Sem vínculo oficial com ETEC/Centro Paula Souza.','Introductory high-school physics, independently organized. No official affiliation with ETEC/Centro Paula Souza.')}</p></div><aside class="rightcol"><section class="panel"><div class="row"><h3>${t('Sua meta diária','Your daily goal')}</h3><span>🎯</span></div><p class="small muted">${t('Um pouquinho a cada dia faz a diferença.','A little every day makes a difference.')}</p><div class="row small"><b>${dayXP} / 30 XP</b><span class="muted">${dayXP>=30?t('Concluída!','Complete!'):t('Você consegue!','You can do it!')}</span></div><div class="progress"><i style="width:${Math.min(100,dayXP/30*100)}%"></i></div><div class="week">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,on=state.dates.includes(key);return `<div class="day">${d.toLocaleDateString(t('pt-BR','en'),{weekday:'narrow'})}<b class="${on?'on':''}">${on?'✓':d.getDate()}</b></div>`}).join('')}</div></section><section class="panel"><h3>${t('Missões da jornada','Journey missions')}</h3><div class="mission"><span class="ico">★</span><div><b>${t('Dê o primeiro passo','Take the first step')}</b><p class="muted">${state.done.length?'✓ ':''}${t('Conclua uma aula · +20 XP','Complete a lesson · +20 XP')}</p></div></div><div class="mission"><span class="ico">⚗</span><div><b>${t('Cientista por um dia','Scientist for a day')}</b><p class="muted">${state.simSeen.length}/8 ${t('experimentos explorados','experiments explored')}</p></div></div><div class="mission"><span class="ico">⚑</span><div><b>${t('Vá além','Go further')}</b><p class="muted">${state.tests.length}/10 ${t('testes concluídos','tests completed')} · +40 XP</p></div></div></section><section class="panel labpromo"><h3>${t('E se você pudesse testar?','What if you could test it?')}</h3><p>${t('Mude uma força. Lance um foguete. Descubra o que acontece.','Change a force. Launch a rocket. Discover what happens.')}</p><a href="#simulators">${t('Entrar no laboratório','Enter the laboratory')} →</a></section><p class="note">${t('Seu progresso fica salvo neste navegador. Sem cadastro, no seu ritmo.','Progress is saved in this browser. No signup, at your pace.')}</p></aside></div>`}
function locked(){return `<div class="panel empty"><span class="ico">🔒</span><h1>${t('Uma descoberta de cada vez','One discovery at a time')}</h1><p>${t('Conclua as etapas anteriores para desbloquear esta atividade.','Complete previous steps to unlock this activity.')}</p><a class="primary" href="#${nextLesson()}">${t('Continuar minha jornada','Continue my journey')}</a></div>`}
function back(){return `<a class="back" href="#home">← ${t('Minha jornada','My journey')}</a>`}
function questionHTML(q){return `<h2>${tr(q.question)}</h2>${q.type==='number'?`<label class="control">${t('Sua resposta numérica','Your numerical answer')}<input class="choiceinput" id="numeric" inputmode="decimal" value="${selection===null?'':esc(selection)}" ${feedback?'disabled':''} placeholder="${t('Digite um número','Enter a number')}"></label>`:`<div class="options ${q.type==='graph'?'graphchoices':''}">${q.options.map((x,i)=>`<button draggable="${q.type==='drag'}" class="option ${selection===i?'selected':''} ${feedback&&i===q.answer?'correct':''}" data-answer="${i}" ${feedback?'disabled':''}>${q.type==='graph'?`<svg viewBox="0 0 180 100" role="img" aria-label="${esc(tr(x))}"><path d="M20 5V80H170" fill="none" stroke="#b7afce" stroke-width="2"/><path d="${['M25 45H160','M25 75L160 10','M25 75Q135 75 160 10'][i]}" fill="none" stroke="#6555de" stroke-width="4"/><text x="4" y="12" font-size="12">x</text><text x="167" y="96" font-size="12">t</text></svg>`:''}<b>${String.fromCharCode(65+i)}.</b> ${tr(x)}</button>`).join('')}</div>`}${q.type==='drag'?`<div id="dropzone" class="dropzone" tabindex="0">${selection===null?t('Arraste a grandeza vetorial para cá, ou toque em uma opção.','Drag the vector quantity here, or tap an option.'):tr(q.options[selection])+' ✓'}</div>`:''}${feedback?`<div class="feedback ${feedback.ok?'confetti':'wrong'}" role="status"><b>${feedback.ok?t('Muito bem! Você descobriu.','Well done! You figured it out.'):t('Vamos entender juntos.','Let’s work it out together.')}</b><p>${tr(q.why)}</p>${!feedback.ok?`<small>${t('Resposta','Answer')}: ${q.type==='number'?q.answer:tr(q.options[q.answer])}</small>`:''}</div><button class="primary" id="advance">${feedback.ok?t('Continuar','Continue'):t('Tentar novamente','Try again')} →</button>`:`<button class="primary" id="check" ${selection===null?'disabled':''}>${t('Verificar resposta','Check answer')}</button>`}`}
function lessonView(u,l){if(!UNITS[u]||!UNITS[u].lessons[l]||!canLesson(u,l))return locked();let q=UNITS[u].lessons[l];if(session?.complete)return completeView(t('Descoberta concluída!','Discovery complete!'),session.newXP?20:0, l<3?`lesson/${u}/${l+1}`:`test/${u}`);return `<div class="lesson">${back()}<span class="eyebrow">${tr(UNITS[u].topic)} · ${l+1}/4</span><h1>${tr(q.title)}</h1><div class="progress"><i style="width:${session?.stage==='quiz'?75:35}%"></i></div>${session?.stage==='quiz'?`<div class="panel">${questionHTML(q)}</div>`:`<div class="panel"><span class="ico" style="font-size:45px">${UNITS[u].icon}</span><p style="font-size:18px">${tr(q.text)}</p><div class="formula">${esc(formula(q.formula))}</div><div class="example"><b>${t('Na vida real','In real life')}</b><p>${tr(q.example)}</p></div><p class="note">${t('Explore o modelo e depois teste sua descoberta.','Explore the model, then test your discovery.')}</p><a class="back" href="#sim/${['motion','motion','forces','energy','torque','hydro','heat','heat','orbit','motion'][u]}">${t('Abrir experimento interativo','Open interactive experiment')} ↗</a><br><button class="primary" id="startquiz">${t('Vamos praticar','Let’s practice')} →</button></div>`}</div>`}
function formula(s){if(!state.lang)return s;return s.replaceAll('sen','sin').replaceAll('Eútil/Erecebida','Euseful/Einput').replaceAll('ρlíquido','ρliquid').replaceAll('Vsubmerso','Vsubmerged').replaceAll('Qfase','Qphase').replaceAll('Qquente','Qhot').replaceAll('Qfrio','Qcold').replaceAll('vórbita','vorbit').replaceAll('condução · convecção · radiação','conduction · convection · radiation').replaceAll('energia recebida ↔ energia emitida','incoming energy ↔ outgoing energy').replaceAll('observar → perguntar → testar','observe → ask → test').replaceAll('média = soma / quantidade','mean = sum / count').replaceAll('independente','independent').replaceAll('dependente','dependent').replaceAll('evidências + análise → conclusão','evidence + analysis → conclusion').replaceAll('273,15','273.15').replaceAll('1,8','1.8').replaceAll('6,6743','6.6743').replaceAll('1.000','1,000').replaceAll('3.600','3,600').replaceAll('3.000','3,000')}
function completeView(title,xp,next){return `<div class="lesson"><section class="panel completion confetti"><span class="ico">🏅</span><h1>${title}</h1><p>${t('Cada ideia aprendida abre uma nova possibilidade.','Every idea learned opens a new possibility.')}</p><div class="formula">${xp?`+${xp} XP`:t('Conhecimento reforçado ✓','Knowledge reinforced ✓')}</div><a class="primary" href="#${next}">${t('Próxima descoberta','Next discovery')} →</a><br><a class="back" style="margin-top:25px" href="#home">${t('Voltar à trilha','Back to the trail')}</a></section></div>`}
function testView(u){if(!UNITS[u]||!unlocked(u)||!UNITS[u].lessons.every((_,l)=>done(u,l)))return locked();if(session?.complete)return completeView(t('Unidade conquistada!','Unit mastered!'),session.newXP?40:0,u<9?`lesson/${u+1}/0`:'achievements');const i=session?.index||0;return `<div class="lesson">${back()}<span class="eyebrow">${t('DESAFIO FINAL','FINAL CHALLENGE')} · ${i+1}/4</span><h1>${tr(UNITS[u].name)}</h1><p class="muted">${t('Aplique as quatro ideias desta unidade.','Apply the four ideas from this unit.')}</p><div class="progress"><i style="width:${i/4*100}%"></i></div><section class="panel">${questionHTML(UNITS[u].lessons[i])}</section></div>`}
function practiceQuestion(key){const [u,l]=key.split('-').map(Number);return l<4?UNITS[u]?.lessons[l]:EXTRA_EXERCISES[u]?.[l-4]}
function practiceView(review){
 const keys=review?state.mistakes:UNITS.flatMap((u,i)=>[...u.lessons,...EXTRA_EXERCISES[i]].map((_,l)=>`${i}-${l}`)).filter(k=>{const [u,l]=k.split('-').map(Number);return canLesson(u,l%4)});
 if(session?.key){const q=practiceQuestion(session.key);return `<div class="lesson"><button class="back" id="practiceback">← ${t('Atividades','Activities')}</button><span class="eyebrow">${review?t('REVISÃO','REVIEW'):t('PRÁTICA','PRACTICE')}</span><h1>${tr(q.title)}</h1><div class="panel">${questionHTML(q)}</div></div>`}
 const heading=`<h1>${review?t('Toda tentativa ensina','Every attempt teaches'):t('Treine suas descobertas','Practice your discoveries')}</h1><p class="muted">${review?t('As questões que precisam de atenção ficam aqui. Acerte para recuperar uma vida, até o máximo de cinco.','Questions needing attention appear here. Answer correctly to recover a life, up to five.'):t('80 exercícios: 40 questões das aulas e 40 desafios extras. Novas atividades são liberadas conforme você avança. A prática não gasta vidas nem concede XP extra.','80 exercises: 40 lesson questions and 40 extra challenges. Activities unlock as you progress. Practice does not cost lives or award extra XP.')}</p>`;
 if(!keys.length)return heading+`<div class="panel empty"><span class="ico">✨</span><h2>${t('Tudo em dia!','All caught up!')}</h2><p>${t('Nenhum erro pendente. Continue descobrindo ou pratique nas atividades.','No pending mistakes. Keep discovering or practice in Exercises.')}</p><a class="primary" href="#exercises">${t('Abrir exercícios','Open exercises')}</a></div>`;
 return heading+UNITS.map((unit,u)=>{const group=keys.filter(k=>Number(k.split('-')[0])===u);if(!group.length)return '';return `<section><div class="sectionhead"><h2>${unit.icon} ${tr(unit.topic)}</h2><small>${group.filter(k=>state.practiceDone.includes(k)).length}/${group.length} ${t('resolvidos','solved')}</small></div><div class="grid">${group.map(k=>{const q=practiceQuestion(k),extra=Number(k.split('-')[1])>=4,solved=state.practiceDone.includes(k);return `<article class="tile"><span class="eyebrow">${extra?t('DESAFIO EXTRA','EXTRA CHALLENGE'):t('DA AULA','FROM THE LESSON')}</span><h3>${tr(q.title)}</h3><p>${q.type==='number'?t('Cálculo · resposta numérica','Calculation · numerical answer'):t('Conceito · escolha sua resposta','Concept · choose your answer')}</p><button class="secondary" data-practice="${k}">${solved?'✓ '+t('Praticar novamente','Practice again'):t('Praticar','Practice')} →</button></article>`}).join('')}</div></section>`}).join('');
}
const badges=[['🌱',bi('Primeiro Passo','First Step'),bi('Conclua uma aula','Complete a lesson'),()=>state.done.length>0],['🛹',bi('Explorador do Movimento','Motion Explorer'),bi('Conclua Cinemática','Complete Kinematics'),()=>state.tests.includes(1)],['🧲',bi('Amigo de Newton','Newton’s Friend'),bi('Conclua Dinâmica','Complete Dynamics'),()=>state.tests.includes(2)],['⚡',bi('Herói da Energia','Energy Hero'),bi('Conclua Energia','Complete Energy'),()=>state.tests.includes(3)],['🪐',bi('Mestre das Órbitas','Orbit Master'),bi('Conclua Astronomia','Complete Astronomy'),()=>state.tests.includes(8)],['🔬',bi('Mente Curiosa','Curious Mind'),bi('Explore os 8 simuladores','Explore all 8 simulators'),()=>state.simSeen.length===8],['🔥',bi('Constelação de Hábitos','Constellation of Habits'),bi('Estude por 3 dias seguidos','Study for 3 consecutive days'),()=>streak()>=3],['🏆',bi('Universo Descoberto','Universe Discovered'),bi('Conclua as 10 unidades','Complete all 10 units'),()=>state.tests.length===10]];
function achievements(){return `<h1>${t('Pequenas vitórias, grandes conquistas','Small victories, big achievements')}</h1><p class="muted">${badges.filter(b=>b[3]()).length}/${badges.length} ${t('conquistas desbloqueadas','achievements unlocked')}</p><div class="grid">${badges.map(b=>`<article class="badge ${b[3]()?'':'locked'}"><span class="ico">${b[0]}</span><div><b>${tr(b[1])}</b><small>${tr(b[2])}</small><small>${b[3]()?'✓ '+t('Conquistada','Earned'):'🔒 '+t('Em construção','In progress')}</small></div></article>`).join('')}</div>`}
function profile(){return `<div class="lesson"><div class="row" style="justify-content:flex-start"><span class="largeavatar">${state.avatar}</span><div><span class="eyebrow">${t('SEU PASSAPORTE CIENTÍFICO','YOUR SCIENCE PASSPORT')}</span><h1>${esc(state.name||t('Explorador','Explorer'))}</h1><b>${t('Nível','Level')} ${1+Math.floor(state.xp/100)}</b></div></div><div class="readouts">${[[t('XP total','Total XP'),state.xp],[t('Sequência diária','Daily streak'),streak()+' '+t('dias','days')],[t('Aulas concluídas','Lessons completed'),`${state.done.length}/40`],[t('Unidades concluídas','Units completed'),`${state.tests.length}/10`],[t('Taxa de acerto','Accuracy'),`${state.answered?Math.round(state.correct/state.answered*100):0}%`],[t('Questões respondidas','Questions answered'),state.answered],[t('Tempo de estudo','Study time'),Math.floor(state.study/60)+' min'],[t('Conquistas','Achievements'),badges.filter(b=>b[3]()).length],[t('Idioma','Language'),t('Português','English')]].map(([a,b])=>`<div class="readout"><small>${a}</small><b>${b}</b></div>`).join('')}</div><section class="panel"><label for="name"><b>${t('Como podemos chamar você?','What should we call you?')}</b></label><input class="textinput" id="name" maxlength="30" value="${esc(state.name)}" placeholder="${t('Seu nome','Your name')}" style="margin:15px 0"><p>${t('Escolha seu avatar','Choose your avatar')}</p><div>${['🧑‍🚀','🦊','🐸','🐱','🤖','🦉'].map(a=>`<button class="avatarpick ${a===state.avatar?'selected':''}" data-avatar="${a}" aria-label="${a}">${a}</button>`).join('')}</div><button class="primary" id="savename" style="margin-top:18px">${t('Salvar perfil','Save profile')}</button></section></div>`}
function settings(){return `<div class="lesson"><h1>${t('Do seu jeito','Make it yours')}</h1><div class="panel"><h2>${t('Idioma e movimento','Language and motion')}</h2><div class="control"><label for="setlang">${t('Idioma','Language')}</label><select id="setlang"><option value="0" ${!state.lang?'selected':''}>Português (Brasil)</option><option value="1" ${state.lang?'selected':''}>English</option></select></div><label><input id="motionpref" type="checkbox" ${state.motion?'checked':''}> ${t('Animações suaves','Gentle animations')}</label><p class="note">${t('Também respeitamos a preferência de movimento reduzido do dispositivo.','We also respect your device’s reduced-motion preference.')}</p></div><div class="panel"><h2>${t('Seu progresso','Your progress')}</h2><p>${t('Os dados ficam apenas neste navegador. Exporte uma cópia para guardar ou transferir seu progresso.','Data stays in this browser. Export a copy to keep or transfer your progress.')}</p><button class="secondary" id="export">${t('Exportar progresso','Export progress')}</button> <label class="secondary" style="display:inline-block;cursor:pointer">${t('Importar progresso','Import progress')}<input type="file" id="import" accept="application/json" style="display:none"></label><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><button class="danger" id="reset">${t('Recomeçar a jornada','Restart the journey')}</button><div id="resetconfirm"></div></div><p class="note">${t('Vidas: uma a cada 30 minutos; revise erros para recuperar. XP é concedido apenas na primeira conclusão de cada aula, teste ou rodada de jogo.','Lives: one every 30 minutes; review mistakes to recover. XP is awarded only for the first completion of each lesson, test or game round.')}</p></div>`}
function simList(){return `<span class="eyebrow">${t('APRENDA EXPERIMENTANDO','LEARN BY EXPERIMENTING')}</span><h1>${t('Seu laboratório de possibilidades','Your laboratory of possibilities')}</h1><p class="muted">${t('Mude uma variável. Observe. Faça uma nova descoberta.','Change a variable. Observe. Make a new discovery.')}</p><div class="grid">${SIMS.map(s=>`<article class="tile"><span class="ico">${s.icon}</span><h2>${tr(s.name)}</h2><p>${tr(s.desc)}</p><a class="primary" href="#sim/${s.id}">${t('Experimentar','Experiment')} →</a></article>`).join('')}</div>`}
function simView(id){const s=SIMS.find(x=>x.id===id);if(!s)return simList();if(!simState||simState.id!==id)simState={id,...Object.fromEntries(s.controls.map(c=>[c[0],c[4]])),material:'water'};return `<a class="back" href="#simulators">← ${t('Laboratório','Laboratory')}</a><div class="row"><div><span class="eyebrow">${t('EXPERIMENTO INTERATIVO','INTERACTIVE EXPERIMENT')}</span><h1>${s.icon} ${tr(s.name)}</h1></div></div><div class="simtabs">${SIMS.map(s=>`<a href="#sim/${s.id}" class="${s.id===id?'active':''}">${tr(s.name)}</a>`).join('')}</div><div class="simlayout"><section class="panel controls">${s.controls.map(c=>`<div class="control"><label for="c-${c[0]}">${tr(c[1])}<b><output id="o-${c[0]}">${fmt(simState[c[0]])}</output> ${c[6]}</b></label><input type="range" id="c-${c[0]}" data-control="${c[0]}" min="${c[2]}" max="${c[3]}" step="${c[5]}" value="${simState[c[0]]}"></div>`).join('')}${id==='heat'?`<div class="control"><label for="material">${t('Material','Material')}</label><select id="material">${[['water',bi('Água','Water')],['aluminum',bi('Alumínio','Aluminum')],['iron',bi('Ferro','Iron')]].map(([v,n])=>`<option value="${v}" ${simState.material===v?'selected':''}>${tr(n)}</option>`).join('')}</select></div>`:''}<button class="secondary" id="simreset">↻ ${t('Restaurar valores','Reset values')}</button></section><section><div class="stage"><canvas id="scene" tabindex="0" role="img" aria-label="${t('Modelo interativo. Arraste para girar; setas do teclado também giram a câmera.','Interactive model. Drag to rotate; keyboard arrows also rotate the camera.')}"></canvas></div><div class="row" style="margin-top:12px"><span class="note">${t('↔ Arraste para girar o modelo 3D · setas do teclado','↔ Drag to rotate the 3D model · keyboard arrows')}</span>${['motion','energy','projectile','orbit','heat'].includes(id)?`<button class="secondary" id="play">▶ ${t('Animar','Animate')}</button>`:''}</div><div class="readouts" id="readouts"></div>${id==='motion'?`<canvas id="motiongraph" class="graph" role="img" aria-label="${t('Gráfico posição em metros versus tempo em segundos','Position in meters versus time in seconds')}"></canvas>`:''}<div class="panel" style="margin-top:16px"><div id="modelnote" class="note"></div></div></section></div>`}
const fmt=(v,n=2)=>Number(v).toLocaleString(t('pt-BR','en'),{maximumFractionDigits:n});
function updateSim(){if(!simState)return;const s=simState,r=Physics[s.id](s);let rows=[],note='';switch(s.id){case'motion':rows=[[bi('Posição','Position'),r.position,'m'],[bi('Velocidade','Velocity'),r.velocity,'m/s'],[bi('Aceleração','Acceleration'),r.acceleration,'m/s²']];note=t('x = x₀ + v₀t + ½at²; v = v₀ + at. Aceleração constante, trajetória retilínea. O gráfico usa a escala indicada; o modelo 3D é esquemático.','x = x₀ + v₀t + ½at²; v = v₀ + at. Constant acceleration, straight path. The graph uses the labeled scale; the 3D model is schematic.');break;
case'forces':rows=[[bi('Peso','Weight'),r.weight,'N'],[bi('Normal','Normal force'),r.normal,'N'],[bi('Atrito','Friction'),r.friction,'N'],[bi('Resultante','Net force'),r.net,'N'],[bi('Aceleração','Acceleration'),r.acceleration,'m/s²']];note=t('Bloco inicialmente parado, força horizontal para a direita. Usamos μ estático = μ cinético. Atrito = min(F, μmg); N = mg; a = (F − atrito)/m. g = 9,8 m/s². Vetores indicam sentido; comprimentos visuais são esquemáticos.','Block initially at rest, horizontal applied force to the right. Static μ equals kinetic μ in this model. Friction = min(F, μmg); N = mg; a = (F − friction)/m. g = 9.8 m/s². Arrows indicate direction; visual lengths are schematic.');break;
case'energy':rows=[[bi('Cinética','Kinetic'),r.kinetic,'J'],[bi('Potencial','Potential'),r.potential,'J'],[bi('Total','Total'),r.total,'J'],[bi('Altura','Height'),r.height,'m'],[bi('Rapidez','Speed'),r.speed,'m/s']];note=t('Queda sem resistência do ar, g = 9,8 m/s². Eₚ = mgh; E꜀ = ½mv². A energia potencial perdida vira cinética. Nível zero: solo. A animação percorre frações da altura para visualizar a transformação, não representa um relógio físico.','Fall without air resistance, g = 9.8 m/s². Eₚ = mgh; Eₖ = ½mv². Lost potential energy becomes kinetic. Zero level: ground. Animation steps through height fractions to show conversion; it is not a physical clock.');break;
case'projectile':rows=[[bi('Alcance','Range'),r.range,'m'],[bi('Altura máxima','Maximum height'),r.maxHeight,'m'],[bi('Tempo de voo','Flight time'),r.flight,'s'],[bi('Posição x','Position x'),r.x,'m'],[bi('Altura y','Height y'),r.y,'m'],[bi('Tempo atual','Current time'),r.t,'s']];note=t('Sem ar; gravidade constante; partida e chegada no mesmo nível. R = v₀²sen(2θ)/g; H = (v₀senθ)²/(2g); T = 2v₀senθ/g. Trajetória reescalada para caber no modelo.','No air; constant gravity; launch and landing at the same height. R = v₀²sin(2θ)/g; H = (v₀sinθ)²/(2g); T = 2v₀sinθ/g. Trajectory rescaled to fit the model.');break;
case'hydro':rows=[[bi('Pressão manométrica','Gauge pressure'),r.gauge,'Pa'],[bi('Pressão absoluta','Absolute pressure'),r.absolute,'Pa'],[bi('Empuxo em equilíbrio*','Equilibrium buoyancy*'),r.buoyancy,'N'],[bi('Peso','Weight'),r.weight,'N'],[bi('Volume submerso','Submerged volume'),r.submerged*100,'%']];note=t('p = 101.325 + ρgh; E = ρgVsub. Líquido incompressível; g = 9,8 m/s². A profundidade controla o ponto de medição da pressão, não a posição do objeto. *Se afunda, mostramos o empuxo totalmente submerso; no fundo também existe normal.','p = 101,325 + ρgh; B = ρgVsub. Incompressible liquid; g = 9.8 m/s². Depth controls the pressure measurement point, not object position. *If sinking, we show fully submerged buoyancy; at the bottom a normal force also acts.');rows.push([bi('Comportamento','Behavior'),r.neutral?t('Equilíbrio neutro','Neutral buoyancy'):r.floats?t('Flutua','Floats'):t('Afunda','Sinks'),'']);break;
case'heat':rows=[[bi('Temperatura final','Final temperature'),r.final,'°C'],[bi('Variação','Change'),r.delta,'°C'],[bi('Calor específico','Specific heat'),r.c,'J/(kg·K)'],[bi('Capacidade térmica','Heat capacity'),r.capacity,'J/K']];note=t('Tfinal = Tinicial + Q/(mc). Sem perdas nem mudança de fase; c constante (água 4.180; alumínio 900; ferro 450 J/(kg·K)). Os limites evitam transições de fase. Partículas são uma representação qualitativa da agitação térmica, não uma simulação molecular.','Tfinal = Tinitial + Q/(mc). No losses or phase changes; constant c (water 4,180; aluminum 900; iron 450 J/(kg·K)). Limits avoid phase transitions. Particles qualitatively represent thermal motion; this is not a molecular simulation.');break;
case'torque':rows=[[bi('Torque esquerdo','Left torque'),r.left,'N·m'],[bi('Torque direito','Right torque'),r.right,'N·m'],[bi('Torque resultante','Net torque'),r.net,'N·m'],[bi('Força do apoio','Support force'),r.support,'N']];note=t('Alavanca inicialmente horizontal, sem massa; forças verticais para baixo. τ = F₁d₁ − F₂d₂; anti-horário positivo. Equilíbrio se τ = 0. A inclinação ilustra a tendência de rotação, não uma posição final de equilíbrio.','Initially horizontal massless lever; downward vertical forces. τ = F₁d₁ − F₂d₂; counterclockwise is positive. Equilibrium if τ = 0. Tilt illustrates rotation tendency, not a final equilibrium position.');break;
case'orbit':rows=[[bi('Velocidade orbital','Orbital speed'),r.speed/1000,'km/s'],[bi('Força gravitacional','Gravitational force'),r.force,'N'],[bi('Período','Period'),r.period/60,'min'],[bi('Aceleração','Acceleration'),r.acceleration,'m/s²']];note=t('Órbita circular ideal, massa central esférica concentrada no centro e satélite muito menos massivo. r é entre centros. v = √(GM/r); F = GMm/r²; T = 2πr/v. G = 6,6743×10⁻¹¹ SI. Tamanhos e tempo de animação não estão em escala real.','Ideal circular orbit, spherical central mass treated at its center and a much smaller satellite mass. r is center-to-center distance. v = √(GM/r); F = GMm/r²; T = 2πr/v. G = 6.6743×10⁻¹¹ SI. Sizes and animation time are not to physical scale.');break}
$('#readouts').innerHTML=rows.map(([label,value,unit])=>`<div class="readout"><small>${tr(label)}</small><b>${typeof value==='number'?fmt(value):value} <span class="small">${unit}</span></b></div>`).join('');$('#modelnote').textContent=note;if(window.currentScene)window.currentScene.update(s,r);if(s.id==='motion')drawGraph(s);}
function drawGraph(s){const c=$('#motiongraph'),ctx=c.getContext('2d'),w=c.width=650,h=c.height=150;ctx.clearRect(0,0,w,h);const vals=Array.from({length:101},(_,i)=>Physics.motion({...s,t:i/10}).position),min=Math.min(0,...vals),max=Math.max(1,...vals),py=v=>115-(v-min)/(max-min)*95;ctx.strokeStyle='#ccc5e2';ctx.beginPath();ctx.moveTo(60,15);ctx.lineTo(60,115);ctx.lineTo(630,115);ctx.stroke();ctx.font='12px sans-serif';ctx.fillStyle='#696179';ctx.fillText('x (m)',6,18);ctx.fillText(fmt(max),6,35);ctx.fillText(fmt(min),6,112);ctx.fillText('0',58,135);ctx.fillText('10',615,135);ctx.fillText('t (s)',310,145);ctx.strokeStyle='#6555de';ctx.lineWidth=3;ctx.beginPath();vals.forEach((v,i)=>i?ctx.lineTo(60+i*5.6,py(v)):ctx.moveTo(60,py(v)));ctx.stroke();ctx.fillStyle='#eea649';ctx.beginPath();ctx.arc(60+s.t*56,py(Physics.motion(s).position),6,0,Math.PI*2);ctx.fill()}
const gameSim=[0,1,0,2,6,4,5,7];
const gameNames=[bi('Corrida do movimento','Motion Race'),bi('Mestre das forças','Force Master'),bi('Encontre o gráfico','Graph Match'),bi('Salto de energia','Energy Jump'),bi('Construtor do equilíbrio','Balance Builder'),bi('Afunda ou flutua?','Sink or Float?'),bi('Resgate térmico','Heat Rescue'),bi('Desafio orbital','Orbit Challenge')];
function gameQuestion(id,round){const n=round+1;const numeric=(q,a,why)=>({question:q,answer:a,why,options:[],type:'number'});switch(id){case 0:return numeric(bi(`Seu rover precisa percorrer ${12*n} m em 4 s. Qual rapidez média em m/s?`,`Your rover must travel ${12*n} m in 4 s. What average speed in m/s?`),3*n,bi(`v = ${12*n}/4 = ${3*n} m/s.`,`v = ${12*n}/4 = ${3*n} m/s.`));case 1:return numeric(bi(`Um robô de ${n+1} kg precisa acelerar a ${n} m/s². Qual força resultante em N?`,`A ${n+1} kg robot needs acceleration of ${n} m/s². What net force in N?`),(n+1)*n,bi(`F = ma = ${n+1} × ${n} = ${(n+1)*n} N.`,`F = ma = ${n+1} × ${n} = ${(n+1)*n} N.`));case 2:return {question:round%2?bi('Qual gráfico posição × tempo indica velocidade positiva constante?','Which position–time graph indicates constant positive velocity?'):bi('Qual gráfico posição × tempo indica repouso?','Which position–time graph indicates rest?'),options:[bi('Horizontal','Horizontal'),bi('Reta crescente','Rising straight line'),bi('Curva crescente','Rising curve')],answer:round%2?1:0,type:'graph',why:bi('A inclinação de posição × tempo é a velocidade. Reta horizontal: zero. Reta crescente: positiva constante.','The slope of position–time is velocity. Horizontal line: zero. Rising straight line: constant positive velocity.')};case 3:return numeric(bi(`Uma bola de 2 kg cai ${n} m a partir do repouso. Use g = 10 m/s². Qual energia cinética ganha, em J?`,`A 2 kg ball falls ${n} m from rest. Use g = 10 m/s². How much kinetic energy does it gain, in J?`),20*n,bi(`ΔE꜀ = mgh = 2 × 10 × ${n} = ${20*n} J.`,`ΔEₖ = mgh = 2 × 10 × ${n} = ${20*n} J.`));case 4:return numeric(bi(`À esquerda: ${10*n} N a 2 m do eixo. À direita: 20 N. A que distância (m) colocar a força direita para equilibrar?`,`Left: ${10*n} N at 2 m from the pivot. Right: 20 N. At what distance (m) should the right force act to balance?`),n,bi(`d = (${10*n} × 2)/20 = ${n} m.`,`d = (${10*n} × 2)/20 = ${n} m.`));case 5:{const rho=[600,1200,800,1500,1000][round];return{question:bi(`Objeto: ${rho} kg/m³. Líquido: 1.000 kg/m³. O que acontece ao soltá-lo submerso?`,`Object: ${rho} kg/m³. Liquid: 1,000 kg/m³. What happens when released underwater?`),options:[bi('Sobe e flutua parcialmente','Rises and floats partly submerged'),bi('Afunda','Sinks'),bi('Equilíbrio neutro','Neutral buoyancy')],answer:rho<1000?0:rho>1000?1:2,why:bi('Compare densidades: menor sobe, maior afunda, igual tem peso e empuxo equilibrados (sem outras forças).','Compare densities: lower rises, higher sinks, equal has balanced weight and buoyancy (with no other forces).')}}case 6:return numeric(bi(`Aqueça 1 kg de material, c = 500 J/(kg·K), em ${n*2} °C. Quanto calor em J, sem perdas?`,`Heat 1 kg of material, c = 500 J/(kg·K), by ${n*2} °C. How much heat in J, with no losses?`),1000*n,bi(`Q = mcΔT = 1 × 500 × ${n*2} = ${1000*n} J.`,`Q = mcΔT = 1 × 500 × ${n*2} = ${1000*n} J.`));case 7:return {question:bi(`Uma órbita circular de raio r tem rapidez de ${6*n} km/s. Para raio ${n*n+2*n+1}r em torno da mesma massa, qual a nova rapidez em km/s? Arredonde para duas casas.`,`A circular orbit of radius r has speed ${6*n} km/s. For radius ${n*n+2*n+1}r around the same mass, what is the new speed in km/s? Round to two decimal places.`),options:[],type:'number',answer:Math.round(6*n/(n+1)*100)/100,why:bi(`v ∝ 1/√r. Divida ${6*n} por ${n+1}: ${(6*n/(n+1)).toFixed(2)} km/s.`,`v ∝ 1/√r. Divide ${6*n} by ${n+1}: ${(6*n/(n+1)).toFixed(2)} km/s.`)}}}
function gamesView(id){if(id===undefined)return `<span class="eyebrow">${t('DESAFIOS COM PROPÓSITO','CHALLENGES WITH PURPOSE')}</span><h1>${t('Uma ideia. Uma missão. Vamos jogar!','One idea. One mission. Let’s play!')}</h1><p class="muted">${t('Cinco rodadas por jogo. Resolva, aprenda e ganhe até 50 XP por jogo.','Five rounds per game. Solve, learn and earn up to 50 XP per game.')}</p><div class="grid">${gameNames.map((name,i)=>`<article class="tile"><span class="ico">${SIMS[gameSim[i]].icon}</span><h2>${tr(name)}</h2><p>${tr(SIMS[gameSim[i]].desc)}</p><small class="muted">${state.games[i]?.length||0}/5 ${t('rodadas conquistadas','rounds mastered')}</small><a class="primary" href="#game/${i}">${t('Jogar','Play')} →</a></article>`).join('')}</div>`;if(!gameNames[id])return gamesView();if(!game||game.id!==id)game={id,round:0,score:0};if(game.round===5)return completeView(t('Missão cumprida!','Mission accomplished!'),game.score,'games');const q=gameQuestion(id,game.round);return `<div class="lesson"><a class="back" href="#games">← ${t('Jogos','Games')}</a><div class="row"><h1>${tr(gameNames[id])}</h1><span class="tag">${game.score} XP</span></div><p class="muted">${t('Rodada','Round')} ${game.round+1}/5 · ${t('Use Física para completar a missão. Tentativas não gastam vidas.','Use physics to complete the mission. Attempts do not cost lives.')}</p><div class="progress"><i style="width:${game.round/5*100}%"></i></div><div class="stage"><canvas id="game-scene" tabindex="0" role="img" aria-label="${t('Modelo 3D da missão; arraste para girar','Mission 3D model; drag to rotate')}"></canvas></div><section class="panel">${questionHTML(q)}</section><a class="back" href="#sim/${SIMS[gameSim[id]].id}">${t('Testar no laboratório','Test in the laboratory')} ↗</a></div>`}
function render(reset=true){if(window.currentScene){window.currentScene.destroy();window.currentScene=null}if(anim){cancelAnimationFrame(anim);anim=null}page=location.hash.slice(1)||'home';if(reset){session={stage:'learn',index:0};selection=null;feedback=null;game=null}recover();const [p,a,b]=page.split('/'),u=Number(a),l=Number(b);let html='';if(p==='home')html=home();else if(p==='lesson')html=lessonView(u,l);else if(p==='test')html=testView(u);else if(p==='unit')html=UNITS[u]&&unlocked(u)?`<h1>${tr(UNITS[u].name)}</h1><p>${tr(UNITS[u].intro)}</p>${unitCard(UNITS[u],u)}`:locked();else if(p==='exercises'||p==='review')html=practiceView(p==='review');else if(p==='achievements')html=achievements();else if(p==='profile')html=profile();else if(p==='settings')html=settings();else if(p==='simulators')html=simList();else if(p==='sim')html=simView(a);else if(p==='games')html=gamesView();else if(p==='game')html=gamesView(u);else html=home();shell(html);bind();if($('#hero-orbit'))window.currentScene=new Scene($('#hero-orbit'),'orbit',{mass:5.972,radius:10000,sat:500},true);if($('#game-scene')){const gs=SIMS[gameSim[u]],gp=Object.fromEntries(gs.controls.map(c=>[c[0],c[4]]));if(u===0){gp.x0=0;gp.v=3*(game.round+1);gp.a=0;gp.t=feedback?.ok?4:0}window.currentScene=new Scene($('#game-scene'),gs.id,gp,false)}if($('#scene')){window.currentScene=new Scene($('#scene'),a,simState,false);updateSim()}if(reset)window.scrollTo({top:0,behavior:'instant'})}
function currentQuestion(){const[p,a,b]=page.split('/');if(p==='lesson')return UNITS[+a].lessons[+b];if(p==='test')return UNITS[+a].lessons[session.index||0];if(p==='game')return gameQuestion(+a,game.round);if(session.key)return practiceQuestion(session.key)}
function check(){const q=currentQuestion();if(!q||feedback||selection===null)return;const mode=page.split('/')[0];if(['lesson','test'].includes(mode)&&state.hearts<=0){notify(t('Revise um erro para recuperar uma vida ou aguarde 30 minutos.','Review a mistake to recover a life or wait 30 minutes.'));return}const val=q.type==='number'?Number(String(selection).trim().replace(',','.')):selection;if(q.type==='number'&&(!String(selection).trim()||!Number.isFinite(val))){notify(t('Digite um número válido.','Enter a valid number.'));return}const ok=q.type==='number'?Math.abs(val-q.answer)<1e-6:val===q.answer;state.answered++;if(ok)state.correct++;if(!ok&&['lesson','test'].includes(mode)){state.hearts=Math.max(0,state.hearts-1);state.heartTime=Date.now();const key=`${page.split('/')[1]}-${mode==='test'?session.index:page.split('/')[2]}`;if(!state.mistakes.includes(key))state.mistakes.push(key)}if(!ok&&mode==='exercises'&&!state.mistakes.includes(session.key))state.mistakes.push(session.key);if(ok&&mode==='exercises')state.mistakes=state.mistakes.filter(k=>k!==session.key);if(ok&&mode==='review'&&state.mistakes.includes(session.key)){state.mistakes=state.mistakes.filter(k=>k!==session.key);state.hearts=Math.min(5,state.hearts+1)}feedback={ok};save();render(false)}
function advance(){if(!feedback)return;if(!feedback.ok){feedback=null;selection=null;render(false);return}const[p,a,b]=page.split('/');if(p==='lesson'){const key=`${a}-${b}`;session.newXP=!state.done.includes(key);if(session.newXP){state.done.push(key);reward(20);if(state.done.length===1)notify(t('🌱 Conquista: Primeiro Passo! +20 XP','🌱 Achievement: First Step! +20 XP'))}session.complete=true}else if(p==='test'){session.index++;if(session.index===4){session.newXP=!state.tests.includes(+a);if(session.newXP){state.tests.push(+a);reward(40)}session.complete=true}}else if(p==='game'){state.games[a]??=[];if(!state.games[a].includes(game.round)){state.games[a].push(game.round);game.score+=10;reward(10)}game.round++}else {if(session.key&&!state.practiceDone.includes(session.key))state.practiceDone.push(session.key);session.key=null}feedback=null;selection=null;save();render(false)}
function bind(){document.querySelectorAll('[data-unit]').forEach(el=>el.onclick=()=>{location.hash=`unit/${el.dataset.unit}`});if($('#startquiz'))$('#startquiz').onclick=()=>{session.stage='quiz';render(false)};document.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>{selection=+el.dataset.answer;render(false)});if($('#numeric'))$('#numeric').oninput=e=>{selection=e.target.value;if($('#check'))$('#check').disabled=!selection.trim()};if($('#dropzone')){document.querySelectorAll('[data-answer]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.answer));$('#dropzone').ondragover=e=>e.preventDefault();$('#dropzone').ondrop=e=>{e.preventDefault();const v=Number(e.dataTransfer.getData('text/plain'));if(!feedback&&Number.isInteger(v)&&v>=0&&v<currentQuestion().options.length){selection=v;render(false)}}}if($('#check'))$('#check').onclick=check;if($('#advance'))$('#advance').onclick=advance;document.querySelectorAll('[data-practice]').forEach(el=>el.onclick=()=>{session.key=el.dataset.practice;feedback=null;selection=null;render(false)});if($('#practiceback'))$('#practiceback').onclick=()=>{session.key=null;selection=null;feedback=null;render(false)};document.querySelectorAll('[data-avatar]').forEach(el=>el.onclick=()=>{state.name=$('#name').value;state.avatar=el.dataset.avatar;save();render(false)});if($('#savename'))$('#savename').onclick=()=>{state.name=$('#name').value.trim();save();render(false);notify(t('Perfil salvo!','Profile saved!'))};if($('#setlang'))$('#setlang').onchange=e=>{state.lang=+e.target.value;save();render(false)};if($('#motionpref'))$('#motionpref').onchange=e=>{state.motion=e.target.checked;save()};if($('#export'))$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='orbita-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};if($('#import'))$('#import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());validateImport(data);state={...fresh(),...data};save();render(false);notify(t('Progresso importado.','Progress imported.'))}catch{notify(t('Arquivo de progresso inválido. Nada foi alterado.','Invalid progress file. Nothing changed.'))}};if($('#reset'))$('#reset').onclick=()=>{$('#resetconfirm').innerHTML=`<div class="feedback wrong"><p>${t('Isso apagará o progresso deste navegador. Exporte uma cópia antes, se quiser guardar.','This erases progress in this browser. Export a copy first if you want to keep it.')}</p><button class="danger" id="confirmreset">${t('Apagar e recomeçar','Erase and restart')}</button> <button class="secondary" id="cancelreset">${t('Cancelar','Cancel')}</button></div>`;$('#cancelreset').onclick=()=>$('#resetconfirm').innerHTML='';$('#confirmreset').onclick=()=>{const lang=state.lang;state=fresh();state.lang=lang;save();location.hash='home'}};document.querySelectorAll('[data-control]').forEach(el=>el.oninput=e=>{simState[el.dataset.control]=+e.target.value;$(`#o-${el.dataset.control}`).textContent=fmt(+e.target.value);if(!state.simSeen.includes(simState.id)){state.simSeen.push(simState.id);save()}updateSim()});if($('#material'))$('#material').onchange=e=>{simState.material=e.target.value;updateSim()};if($('#simreset'))$('#simreset').onclick=()=>{simState=null;render(false)};if($('#play'))$('#play').onclick=playSim;}
function validateImport(d){if(!d||typeof d!=='object'||![0,1].includes(d.lang)||typeof d.name!=='string'||d.name.length>30||!['🧑‍🚀','🦊','🐸','🐱','🤖','🦉'].includes(d.avatar))throw Error('profile');for(const k of ['xp','answered','correct','hearts','heartTime','study'])if(!Number.isFinite(d[k])||d[k]<0)throw Error(k);if(d.hearts>5||d.correct>d.answered)throw Error('range');for(const k of ['done','mistakes'])if(!Array.isArray(d[k])||d[k].some(v=>!(k==='done'?/^\d-[0-3]$/:/^\d-[0-7]$/).test(v)))throw Error(k);if(d.practiceDone!==undefined&&(!Array.isArray(d.practiceDone)||d.practiceDone.some(v=>!/^\d-[0-7]$/.test(v))))throw Error('practiceDone');if(!Array.isArray(d.tests)||d.tests.some(v=>!Number.isInteger(v)||v<0||v>9))throw Error('tests');if(!Array.isArray(d.dates)||d.dates.some(v=>!/^\d{4}-\d{2}-\d{2}$/.test(v)))throw Error('dates');if(!Array.isArray(d.simSeen)||d.simSeen.some(v=>!SIMS.some(s=>s.id===v)))throw Error('sims');if(!d.games||typeof d.games!=='object'||Object.entries(d.games).some(([k,v])=>!/^\d$/.test(k)||+k>7||!Array.isArray(v)||v.some(n=>!Number.isInteger(n)||n<0||n>4)))throw Error('games');if(!d.daily||typeof d.daily!=='object'||Object.values(d.daily).some(v=>!Number.isFinite(v)||v<0))throw Error('daily')}
function playSim(){if(anim){cancelAnimationFrame(anim);anim=null;$('#play').textContent='▶ '+t('Animar','Animate');return}if(['heat','orbit'].includes(simState.id)){window.currentScene.playing=!window.currentScene.playing;$('#play').textContent=(window.currentScene.playing?'❚❚ ':'▶ ')+t(window.currentScene.playing?'Pausar':'Animar',window.currentScene.playing?'Pause':'Animate');return}const key=simState.id==='motion'?'t':'p',max=key==='t'?10:1;if(simState[key]>=max)simState[key]=0;let prev=performance.now();$('#play').textContent='❚❚ '+t('Pausar','Pause');function step(now){const dt=(now-prev)/1000;prev=now;simState[key]=Math.min(max,simState[key]+dt*(key==='t'?1:.16));$(`#c-${key}`).value=simState[key];$(`#o-${key}`).textContent=fmt(simState[key]);updateSim();if(simState[key]<max)anim=requestAnimationFrame(step);else{anim=null;$('#play').textContent='▶ '+t('Animar','Animate')}}anim=requestAnimationFrame(step)}
window.addEventListener('hashchange',()=>render());setInterval(()=>{if(!document.hidden&&['lesson','test','sim','game','review','exercises'].includes(page.split('/')[0])){state.study+=15;save()}},15000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_learning_progress',description:'Read local learning progress without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({xp:state.xp,lessonsCompleted:state.done.length,unitsCompleted:state.tests.length,language:state.lang?'en':'pt-BR'})})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_physics_simulator',description:'Open a physics simulator. Does not complete lessons or grant rewards.',inputSchema:{type:'object',properties:{id:{type:'string',enum:SIMS.map(s=>s.id)}},required:['id'],additionalProperties:false},execute:input=>{if(!input||!SIMS.some(s=>s.id===input.id))throw Error('Unknown simulator');history.replaceState(null,'',`#sim/${input.id}`);render();return{id:input.id,opened:true}}})).catch(()=>{})}catch{}}
